  "hypothesis": "Replacing the fixed five-point mixture schedule with continuous, kink-aware line searches will reveal improving packet remeshings missed by the parent and increase the verified score.",
  "rationale": "The parent tests only five mixture fractions, although the maximum-convolution denominator makes the objective sharply kinked and can confine improvements to narrow intervals. The quadratic convolution along each mixture permits inexpensive continuous searches using a quartic numerator and a rigorously screened envelope of quadratic peak candidates, while retaining exact final verification.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'proposals': (24, 6, 64),
    'width_step': (1.0, 0.25, 8.0),
    'reserve': (0.70, 0.5, 0.75)
}

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['reserve']) * budget_s
    rng = np.random.default_rng(seed)
    def alive(margin=0.0):
        return time.monotonic() + margin < deadline
    def exact(f):
        f = np.maximum(f, 0.0)
        c = oaconvolve(f, f, mode='full')
        m = len(c)
        dx = np.diff(np.linspace(-0.5, 0.5, m + 2))
        y = np.concatenate(([0.0], c, [0.0]))
        num = float(np.sum((dx/3.0)*(y[:-1]**2+y[:-1]*y[1:]+y[1:]**2)))
        return num / ((np.sum(np.abs(c))/(m+1))*np.max(np.abs(c)))
    if init is None:
        return {'values': [1.0]}
    if 'values' in init:
        raw = init['values']
    else:
        raw = np.zeros(int(init['length']))
        for a,v in init['packets']:
            if not alive(4):
                return init
            raw[int(a):int(a)+len(v)] += np.asarray(v)
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    baseline = exact(f)
    if not alive(6) or len(f) < 4:
        return init
    n = len(f)
    f = f / np.max(f)
    edges = np.diff(np.r_[False, f > 0, False].astype(np.int8))
    aa = np.flatnonzero(edges == 1)
    bb = np.flatnonzero(edges == -1)
    if len(aa) < 2:
        return init
    mass = np.r_[0.0, np.cumsum(f)]
    heavy = int(np.argmax(mass[bb]-mass[aa]))
    prefixes = []
    for a,b in zip(aa,bb):
        if not alive(5):
            return init
        prefixes.append(np.r_[0.0,np.cumsum(f[a:b])])
    nc = 2*n-1
    L = next_fast_len(nc)
    F = rfft(f,L,workers=1)
    c = irfft(F*F,L,workers=1)[:nc]
    best_score = baseline
    best = None
    step = float(params['width_step'])
    specs = []
    for delta in (step,-step,2*step,-2*step,4*step,-4*step):
        if not alive(4):
            return init
        for anchor in (0.5,0.0,1.0):
            if not alive(4):
                return init
            specs.append((delta,anchor,0))
    specs += [(step,.5,1),(-step,.5,1),(2*step,.5,2),(-2*step,.5,2),(.20,.5,3),(-.20,.5,3)]
    for j in range(max(0,int(params['proposals'])-len(specs))):
        if not alive(5):
            break
        specs.append((float(rng.choice([-1,1]))*step*float(rng.uniform(.5,5)),float(rng.choice([0,.5,1])),int(rng.integers(0,3))))
    # Polarization of the verifier's quadratic convolution numerator.
    def bilinear(u,v):
        return float(2*np.dot(u,v)+.5*(np.dot(u[:-1],v[1:])+np.dot(v[:-1],u[1:])))
    q0 = bilinear(c,c)
    sum0 = float(np.sum(c))
    peak_index = int(np.argmax(c))
    for delta,anchor,mode in specs[:int(params['proposals'])]:
        if not alive(6):
            break
        g = np.zeros(n,dtype=np.float64)
        complete = True
        for j,(a,b) in enumerate(zip(aa,bb)):
            if not alive(5):
                complete = False
                break
            a,b = int(a),int(b)
            w = b-a
            if j == heavy:
                g[a:b] += f[a:b]
                continue
            x = (a+b)/(2.0*n)
            if mode == 1:
                change = delta*(2*x-1)
            elif mode == 2:
                change = delta*np.cos(2*np.pi*x)
            elif mode == 3:
                change = delta*w
            else:
                change = delta
            new_w = max(.25,w+change)
            left = a-anchor*(new_w-w)
            right = left+new_w
            if left < 0:
                right -= left
                left = 0.0
            if right > n:
                left -= right-n
                right = float(n)
            left = max(0.0,left)
            actual = right-left
            if actual <= 0:
                complete = False
                break
            lo = max(0,int(np.floor(left)))
            hi = min(n,int(np.ceil(right)))
            boundaries = np.arange(lo,hi+1,dtype=np.float64)
            old = np.clip((boundaries-left)*(w/actual),0.0,float(w))
            ix = np.minimum(np.floor(old).astype(np.int64),w-1)
            integral = prefixes[j][ix]+(old-ix)*f[a+ix]
            g[lo:hi] += np.maximum(np.diff(integral),0.0)
        if not complete or not alive(5):
            break
        d = g-f
        D = rfft(d,L,workers=1)
        cd = 2*irfft(F*D,L,workers=1)[:nc]
        dd = irfft(D*D,L,workers=1)[:nc]
        if not alive(4):
            break
        q = np.array([q0,2*bilinear(c,cd),bilinear(cd,cd)+2*bilinear(c,dd),2*bilinear(cd,dd),bilinear(dd,dd)])
        sums = (sum0,float(np.sum(cd)),float(np.sum(dd)))
        # The initial peak supplies a lower bound on the envelope throughout
        # [0,1]. A quadratic's Bernstein coefficients bound it from above.
        p = peak_index
        lower = min(float(c[p]),float(c[p]+cd[p]+dd[p]))
        if dd[p] > 0:
            vertex = -cd[p]/(2*dd[p])
            if 0 < vertex < 1:
                lower = min(lower,float(c[p]+vertex*cd[p]+vertex*vertex*dd[p]))
        upper = np.maximum(np.maximum(c,c+.5*cd),c+cd+dd)
        keep = upper >= lower-1e-10*max(1.0,float(c[p]))
        ca,cb,cc = c[keep],cd[keep],dd[keep]
        del upper,keep
        winner = None
        predicted = best_score
        def objective(a):
            if not alive(2.5):
                return 1e20
            numerator = float(np.polynomial.polynomial.polyval(a,q))
            denominator = 3*(sums[0]+a*sums[1]+a*a*sums[2])*float(np.max(ca+a*cb+a*a*cc))
            return -numerator/denominator if denominator > 0 else 1e20
        grid = np.array([0.,1e-7,1e-6,1e-5,1e-4,.001,.0078125,.03125,.125,.3,.5,.75,1.])
        scores = []
        for a in grid:
            if not alive(3):
                break
            val = -objective(float(a))
            scores.append(val)
            if a > 0 and val > predicted+2e-13:
                predicted,winner = val,float(a)
        if len(scores) == len(grid):
            # Refine each sampled local maximum, including endpoint maxima.
            for k in range(len(grid)):
                if not alive(3):
                    break
                if k > 0 and scores[k] < scores[k-1]:
                    continue
                if k+1 < len(grid) and scores[k] < scores[k+1]:
                    continue
                lo = float(grid[max(0,k-1)])
                hi = float(grid[min(len(grid)-1,k+1)])
                if hi <= lo:
                    continue
                result = minimize_scalar(objective,bounds=(lo,hi),method='bounded',options={'xatol':1e-11,'maxiter':45})
                val = -float(result.fun)
                if val > predicted+2e-13:
                    predicted,winner = val,float(result.x)
        if winner is not None and alive(2.5):
            proposal = np.maximum(f+winner*d,0.0)
            verified = exact(proposal)
            if verified > best_score:
                best_score,best = verified,proposal
    if best is None:
        return init
    transitions = np.diff(np.r_[False,best > 0,False].astype(np.int8))
    starts = np.flatnonzero(transitions == 1)
    stops = np.flatnonzero(transitions == -1)
    packets = []
    for a,b in zip(starts,stops):
        if time.monotonic() > start+.88*budget_s:
            return init
        packets.append([int(a),best[a:b].tolist()])
    return {'length':n,'packets':packets}
